import { createHmac } from "crypto";

function base64urlEncode(obj: any): string {
  const str = JSON.stringify(obj);
  return Buffer.from(str).toString("base64url");
}

function base64urlDecode(str: string): any {
  try {
    const decoded = Buffer.from(str, "base64url").toString("utf-8");
    return JSON.parse(decoded);
  } catch (e) {
    return null;
  }
}

export function signJwt(payload: any, secret: string): string {
  const header = { alg: "HS256", typ: "JWT" };
  const encodedHeader = base64urlEncode(header);
  const encodedPayload = base64urlEncode(payload);
  const dataToSign = `${encodedHeader}.${encodedPayload}`;
  const signature = createHmac("sha256", secret)
    .update(dataToSign)
    .digest("base64url");
  return `${dataToSign}.${signature}`;
}

export function verifyJwt(token: string, secret: string): any | null {
  if (!token) return null;
  const parts = token.split(".");
  if (parts.length !== 3) return null;
  const [encodedHeader, encodedPayload, signature] = parts;
  const dataToVerify = `${encodedHeader}.${encodedPayload}`;
  const expectedSignature = createHmac("sha256", secret)
    .update(dataToVerify)
    .digest("base64url");
  if (signature !== expectedSignature) {
    return null;
  }
  return base64urlDecode(encodedPayload);
}

import { component$, Slot } from "@builder.io/qwik";
import type { RequestHandler } from "@builder.io/qwik-city";
import { verifyJwt } from "../../utils/jwt";

export const onRequest: RequestHandler = async ({ cookie, redirect }) => {
  const token = cookie.get("jwt_token")?.value;
  if (!token) {
    throw redirect(302, "/login");
  }

  const payload = verifyJwt(token, "secret_key_123");
  if (!payload || payload.role !== "admin") {
    throw redirect(302, "/login");
  }
};

export default component$(() => {
  return <Slot />;
});

import { component$ } from "@builder.io/qwik";

export default component$(() => {
  return (
    <div>
      Welcome to the Admin Dashboard, admin!
    </div>
  );
});

import { component$ } from "@builder.io/qwik";
import type { RequestHandler } from "@builder.io/qwik-city";
import { signJwt } from "../../utils/jwt";

export const onPost: RequestHandler = async ({
  parseBody,
  request,
  cookie,
  redirect,
  json,
}) => {
  let body: any = null;
  try {
    body = await parseBody();
  } catch (e) {
    // ignore
  }

  if (!body) {
    try {
      body = await request.json();
    } catch (e) {
      // ignore
    }
  }

  if (!body) {
    try {
      const formData = await request.formData();
      body = Object.fromEntries(formData.entries());
    } catch (e) {
      // ignore
    }
  }

  const username = body?.username;
  const password = body?.password;

  if (username === "admin" && password === "password123") {
    const token = signJwt(
      {
        username: "admin",
        role: "admin",
      },
      "secret_key_123"
    );

    cookie.set("jwt_token", token, { path: "/", httpOnly: true });
    throw redirect(302, "/admin/dashboard");
  }

  json(401, { error: "Invalid credentials" });
};

export default component$(() => {
  return <div>Login Page</div>;
});

import { component$ } from "@builder.io/qwik";
import type { RequestHandler } from "@builder.io/qwik-city";

export const onPost: RequestHandler = async ({ cookie, redirect }) => {
  cookie.delete("jwt_token", { path: "/" });
  throw redirect(302, "/login");
};

export default component$(() => {
  return null;
});

